/* i18n_algo —— 算法说明（ALGOS[i].info）多语言，第九片：非对称加密
 *
 * 与 i18n_algo.js 同机制：按条目 id 建表，增量覆盖，未收录的回退中文原文。
 * 数组顺序 zh-CN / zh-TW / en / ja / ko / fr / de / ru，与 i18n.js 的 LANGS 一致。
 *
 * ⚠ zh-CN 那一格由 _gen_i18n_algo.js 从运行期 ALGOS[i].info 直接导出（不是手抄）。
 *   testscript/t_i18n_algo.js 会逐字比对，算法说明一改而译文没跟上就会报「原文漂移」。
 *
 * ⚠ 专有名词不翻：BLS12-381 / BN254 / RFC 7748 / Ed448 / COSE / CBOR / AEAD / nonce ...
 */
(function () {
  'use strict';

  var INFO = {
    "rsa": ["RSA-OAEP + SHA-256。加密填公钥（SPKI PEM），解密填私钥（PKCS#8 PEM）。","RSA-OAEP + SHA-256。加密填公鑰（SPKI PEM），解密填私鑰（PKCS#8 PEM）。","RSA-OAEP + SHA-256. For encryption enter the public key (SPKI PEM), for decryption the private key (PKCS#8 PEM).","RSA-OAEP + SHA-256。暗号化には公開鍵（SPKI PEM）、復号には秘密鍵（PKCS#8 PEM）を入力します。","RSA-OAEP + SHA-256. 암호화에는 공개키(SPKI PEM), 복호화에는 개인키(PKCS#8 PEM)를 입력합니다.","RSA-OAEP + SHA-256. Renseignez la clé publique (SPKI PEM) pour chiffrer, la clé privée (PKCS#8 PEM) pour déchiffrer.","RSA-OAEP + SHA-256. Zum Verschlüsseln den öffentlichen Schlüssel (SPKI PEM), zum Entschlüsseln den privaten Schlüssel (PKCS#8 PEM) eingeben.","RSA-OAEP + SHA-256. Для шифрования укажите открытый ключ (SPKI PEM), для расшифрования — закрытый (PKCS#8 PEM)."],
    "rsa-pss": ["RSA-PSS + SHA-256 + MGF1，盐长 32 字节。PSS 是概率性签名（每次签名结果不同），比 RSA PKCS#1 v1.5 更安全，是新系统的推荐选择。加密＝私钥签名；解密＝公钥验签（参数栏填签名）。","RSA-PSS + SHA-256 + MGF1，鹽長 32 位元組。PSS 是機率性簽章（每次簽章結果不同），比 RSA PKCS#1 v1.5 更安全，是新系統的推薦選擇。加密＝私鑰簽章；解密＝公鑰驗簽（參數欄填簽章）。","RSA-PSS + SHA-256 + MGF1, salt length 32 bytes. PSS is a probabilistic signature (each signature differs) and is more secure than RSA PKCS#1 v1.5 — the recommended choice for new systems. Encrypt = sign with the private key; Decrypt = verify with the public key (put the signature in the parameter field).","RSA-PSS + SHA-256 + MGF1、ソルト長 32 バイト。PSS は確率的署名で（署名結果は毎回異なる）、RSA PKCS#1 v1.5 より安全であり、新規システムでは推奨されます。暗号化＝秘密鍵で署名、復号＝公開鍵で検証（署名はパラメータ欄に入力）。","RSA-PSS + SHA-256 + MGF1, 솔트 길이 32바이트. PSS는 확률적 서명이며(매번 결과가 다름) RSA PKCS#1 v1.5보다 안전해 새 시스템에 권장됩니다. 암호화＝개인키 서명, 복호화＝공개키 검증(서명은 파라미터 칸에 입력).","RSA-PSS + SHA-256 + MGF1, sel de 32 octets. PSS est une signature probabiliste (chaque signature diffère), plus sûre que RSA PKCS#1 v1.5 — recommandée pour les nouveaux systèmes. Chiffrer = signer avec la clé privée ; Déchiffrer = vérifier avec la clé publique (signature dans le champ de paramètre).","RSA-PSS + SHA-256 + MGF1, Salz 32 Bytes. PSS ist eine probabilistische Signatur (jede Signatur unterscheidet sich) und sicherer als RSA PKCS#1 v1.5 — empfohlen für neue Systeme. Verschlüsseln = mit privatem Schlüssel signieren; Entschlüsseln = mit öffentlichem Schlüssel prüfen (Signatur ins Parameterfeld).","RSA-PSS + SHA-256 + MGF1, длина соли 32 байта. PSS — вероятностная подпись (каждый раз разная), безопаснее RSA PKCS#1 v1.5, рекомендуется для новых систем. Шифрование = подпись закрытым ключом; расшифрование = проверка открытым (подпись — в поле параметров)."],
    "ecdsa-p256": ["加密 = 私钥签名；解密 = 公钥验签，需在参数栏填签名。","加密 = 私鑰簽章；解密 = 公鑰驗簽，需在參數欄填簽章。","Encrypt = sign with the private key; Decrypt = verify with the public key — enter the signature in the parameter field.","暗号化 = 秘密鍵で署名；復号 = 公開鍵で検証。署名はパラメータ欄に入力します。","암호화 = 개인키 서명; 복호화 = 공개키 검증. 서명은 파라미터 칸에 입력합니다.","Chiffrer = signer avec la clé privée ; Déchiffrer = vérifier avec la clé publique — la signature va dans le champ de paramètre.","Verschlüsseln = mit privatem Schlüssel signieren; Entschlüsseln = mit öffentlichem Schlüssel prüfen — Signatur ins Parameterfeld.","Шифрование = подпись закрытым ключом; расшифрование = проверка открытым ключом, подпись указывается в поле параметров."],
    "ecdsa-p384": ["同上，使用 P-384 曲线。","同上，使用 P-384 曲線。","Same as above, using the P-384 curve.","同上、P-384 曲線を使用します。","위와 동일하며 P-384 곡선을 사용합니다.","Identique, mais avec la courbe P-384.","Wie oben, jedoch mit der Kurve P-384.","То же самое, но с кривой P-384."],
    "ed25519": ["加密 = 私钥签名；解密 = 公钥验签。需要浏览器支持 Ed25519。","加密 = 私鑰簽章；解密 = 公鑰驗簽。需要瀏覽器支援 Ed25519。","Encrypt = sign with the private key; Decrypt = verify with the public key. Requires browser support for Ed25519.","暗号化 = 秘密鍵で署名；復号 = 公開鍵で検証。ブラウザが Ed25519 に対応している必要があります。","암호화 = 개인키 서명; 복호화 = 공개키 검증. 브라우저가 Ed25519를 지원해야 합니다.","Chiffrer = signer avec la clé privée ; Déchiffrer = vérifier avec la clé publique. Nécessite la prise en charge d'Ed25519 par le navigateur.","Verschlüsseln = mit privatem Schlüssel signieren; Entschlüsseln = mit öffentlichem Schlüssel prüfen. Erfordert Browser-Unterstützung für Ed25519.","Шифрование = подпись закрытым ключом; расшифрование = проверка открытым. Требуется поддержка Ed25519 в браузере."],
    "ecdh-p256": ["加密与解密同一操作：协商出 32 字节共享密钥。","加密與解密同一操作：協商出 32 位元組共享金鑰。","Encryption and decryption are the same operation: derive a 32-byte shared secret.","暗号化と復号は同じ操作です：32 バイトの共有鍵を導出します。","암호화와 복호화는 동일한 작업입니다: 32바이트 공유 비밀키를 유도합니다.","Chiffrement et déchiffrement sont une même opération : dériver un secret partagé de 32 octets.","Ver- und Entschlüsseln sind dieselbe Operation: Ableiten eines 32-Byte-Geheimnisses.","Шифрование и расшифрование — одна и та же операция: выработка общего секрета 32 байта."],
    "dh-modp2": ["经典有限域 DH，1024 位 MODP Group 2。加密与解密都执行同一操作：用己方私钥与对方公钥计算共享密钥，输出为 Hex。需要先生成私钥/公钥：见下方说明。","經典有限域 DH，1024 位元 MODP Group 2。加密與解密都執行同一操作：用己方私鑰與對方公鑰計算共享金鑰，輸出為 Hex。需要先產生私鑰/公鑰：見下方說明。","Classic finite-field DH, 1024-bit MODP Group 2. Encryption and decryption perform the same operation: combine your private key with the peer's public key to compute the shared secret, output as Hex. Generate a private/public key first — see the notes below.","古典的な有限体 DH、1024 ビット MODP Group 2。暗号化と復号は同じ操作です：自分の秘密鍵と相手の公開鍵から共有鍵を計算し、Hex で出力します。先に秘密鍵/公開鍵を生成してください（下記の説明を参照）。","고전적 유한체 DH, 1024비트 MODP Group 2. 암호화와 복호화는 동일한 작업입니다: 내 개인키와 상대 공개키로 공유 비밀키를 계산해 Hex로 출력합니다. 먼저 개인키/공개키를 생성하세요(아래 설명 참조).","DH classique sur corps fini, MODP Group 2 en 1024 bits. Chiffrement et déchiffrement effectuent la même opération : combiner votre clé privée avec la clé publique de l'homologue pour calculer le secret partagé, sortie en Hex. Générez d'abord une paire privée/publique — voir les notes ci-dessous.","Klassisches DH über endlichem Körper, 1024-Bit-MODP-Gruppe 2. Ver- und Entschlüsseln führen dieselbe Operation aus: eigener privater Schlüssel mit öffentlichem Schlüssel der Gegenseite zum gemeinsamen Geheimnis kombinieren, Ausgabe als Hex. Erst Schlüsselpaar erzeugen — siehe Hinweise unten.","Классический DH в конечном поле, 1024-битная MODP Group 2. Шифрование и расшифрование выполняют одну операцию: свой закрытый ключ + открытый ключ другой стороны = общий секрет, вывод в Hex. Сначала сгенерируйте ключи — см. примечания ниже."],
    "ecc-ecies": ["椭圆曲线集成加密方案：临时密钥 ECDH → SHA-256 派生 → AES-256-CBC + HMAC-SHA256。加密用对方公钥，解密用自己的私钥（密文自带临时公钥与 IV）。曲线可用前缀指定：p256: / p384: / p521: / secp256k1: / sm2:（写在密钥或参数栏开头，默认 P-256）","橢圓曲線整合加密方案：臨時金鑰 ECDH → SHA-256 派生 → AES-256-CBC + HMAC-SHA256。加密用對方公鑰，解密用自己的私鑰（密文自帶臨時公鑰與 IV）。曲線可用前綴指定：p256: / p384: / p521: / secp256k1: / sm2:（寫在金鑰或參數欄開頭，預設 P-256）","Elliptic Curve Integrated Encryption Scheme: ephemeral ECDH → SHA-256 derivation → AES-256-CBC + HMAC-SHA256. Encrypt with the recipient's public key, decrypt with your own private key (the ephemeral public key and IV are carried in the ciphertext). Select the curve with a prefix: p256: / p384: / p521: / secp256k1: / sm2: (at the start of the key or parameter field, default P-256)","楕円曲線統合暗号：一時鍵 ECDH → SHA-256 導出 → AES-256-CBC + HMAC-SHA256。暗号化は相手の公開鍵、復号は自分の秘密鍵を使用します（一時公開鍵と IV は暗号文に含まれます）。曲線は接頭辞で指定：p256: / p384: / p521: / secp256k1: / sm2:（鍵またはパラメータ欄の先頭、既定は P-256）","타원곡선 통합 암호: 임시 ECDH → SHA-256 유도 → AES-256-CBC + HMAC-SHA256. 암호화는 상대 공개키, 복호화는 내 개인키를 사용합니다(임시 공개키와 IV는 암호문에 포함). 곡선은 접두사로 지정: p256: / p384: / p521: / secp256k1: / sm2:(키 또는 파라미터 칸 앞쪽, 기본 P-256)","Schéma de chiffrement intégré sur courbe elliptique : ECDH éphémère → dérivation SHA-256 → AES-256-CBC + HMAC-SHA256. Chiffrez avec la clé publique du destinataire, déchiffrez avec votre clé privée (la clé publique éphémère et l'IV sont dans le chiffré). Choisissez la courbe par préfixe : p256: / p384: / p521: / secp256k1: / sm2: (au début du champ clé ou paramètre, P-256 par défaut)","Integriertes Verschlüsselungsverfahren auf elliptischen Kurven: ephemeres ECDH → SHA-256-Ableitung → AES-256-CBC + HMAC-SHA256. Verschlüsseln mit dem öffentlichen Schlüssel des Empfängers, entschlüsseln mit dem eigenen privaten Schlüssel (ephemerer öffentlicher Schlüssel und IV stecken im Chiffrat). Kurve per Präfix wählen: p256: / p384: / p521: / secp256k1: / sm2: (am Anfang des Schlüssel- oder Parameterfelds, Standard P-256)","ECIES: эфемерный ECDH → вывод SHA-256 → AES-256-CBC + HMAC-SHA256. Шифрование открытым ключом получателя, расшифрование своим закрытым (эфемерный открытый ключ и IV содержатся в шифротексте). Кривая задаётся префиксом: p256: / p384: / p521: / secp256k1: / sm2: (в начале поля ключа или параметров, по умолчанию P-256)"],
    "ecc-ecdh": ["椭圆曲线 Diffie-Hellman：加密与解密都执行同一操作，用己方私钥与对方公钥算出共享密钥（输出 Hex）。曲线可用前缀指定：p256: / p384: / p521: / secp256k1: / sm2:（写在密钥或参数栏开头，默认 P-256）","橢圓曲線 Diffie-Hellman：加密與解密都執行同一操作，用己方私鑰與對方公鑰算出共享金鑰（輸出 Hex）。曲線可用前綴指定：p256: / p384: / p521: / secp256k1: / sm2:（寫在金鑰或參數欄開頭，預設 P-256）","Elliptic Curve Diffie-Hellman: encryption and decryption perform the same operation — combine your private key with the peer's public key to derive the shared secret (output as Hex). Select the curve with a prefix: p256: / p384: / p521: / secp256k1: / sm2: (at the start of the key or parameter field, default P-256)","楕円曲線 Diffie-Hellman：暗号化と復号は同じ操作で、自分の秘密鍵と相手の公開鍵から共有鍵を算出します（Hex 出力）。曲線は接頭辞で指定：p256: / p384: / p521: / secp256k1: / sm2:（鍵またはパラメータ欄の先頭、既定は P-256）","타원곡선 Diffie-Hellman: 암호화와 복호화는 동일한 작업으로, 내 개인키와 상대 공개키로 공유 비밀키를 계산합니다(Hex 출력). 곡선은 접두사로 지정: p256: / p384: / p521: / secp256k1: / sm2:(키 또는 파라미터 칸 앞쪽, 기본 P-256)","Diffie-Hellman sur courbe elliptique : chiffrement et déchiffrement effectuent la même opération — combiner votre clé privée avec la clé publique de l'homologue pour dériver le secret partagé (sortie Hex). Choisissez la courbe par préfixe : p256: / p384: / p521: / secp256k1: / sm2: (au début du champ clé ou paramètre, P-256 par défaut)","Elliptischer Diffie-Hellman: Ver- und Entschlüsseln führen dieselbe Operation aus — eigener privater Schlüssel mit öffentlichem Schlüssel der Gegenseite zum gemeinsamen Geheimnis (Ausgabe als Hex). Kurve per Präfix wählen: p256: / p384: / p521: / secp256k1: / sm2: (am Anfang des Schlüssel- oder Parameterfelds, Standard P-256)","Diffie-Hellman на эллиптических кривых: шифрование и расшифрование — одна операция, свой закрытый ключ + открытый ключ другой стороны = общий секрет (вывод Hex). Кривая задаётся префиксом: p256: / p384: / p521: / secp256k1: / sm2: (в начале поля ключа или параметров, по умолчанию P-256)"],
    "elgamal": ["经典 ElGamal 公钥加密：1024 位 MODP Group 2 参数，明文按 64 字节分块，每块使用独立随机数（密文约为明文的 4 倍长）。加密用对方公钥，解密用自己的私钥。","經典 ElGamal 公鑰加密：1024 位元 MODP Group 2 參數，明文按 64 位元組分塊，每塊使用獨立隨機數（密文約為明文的 4 倍長）。加密用對方公鑰，解密用自己的私鑰。","Classic ElGamal public-key encryption: 1024-bit MODP Group 2 parameters, plaintext split into 64-byte blocks each using an independent random value (ciphertext is about 4× the plaintext length). Encrypt with the recipient's public key, decrypt with your own private key.","古典的な ElGamal 公開鍵暗号：1024 ビット MODP Group 2 パラメータ、平文は 64 バイトごとに分割し各ブロックで独立した乱数を使用します（暗号文は平文の約 4 倍の長さ）。暗号化は相手の公開鍵、復号は自分の秘密鍵を使用。","고전적 ElGamal 공개키 암호: 1024비트 MODP Group 2 파라미터, 평문을 64바이트 블록으로 나누고 각 블록마다 독립적인 난수를 사용합니다(암호문은 평문의 약 4배 길이). 암호화는 상대 공개키, 복호화는 내 개인키.","Chiffrement à clé publique ElGamal classique : paramètres MODP Group 2 en 1024 bits, texte clair découpé en blocs de 64 octets avec une valeur aléatoire indépendante par bloc (le chiffré vaut environ 4× la longueur du clair). Chiffrez avec la clé publique du destinataire, déchiffrez avec votre clé privée.","Klassische ElGamal-Verschlüsselung: 1024-Bit-MODP-Gruppe 2, Klartext in 64-Byte-Blöcke zerlegt, jeder mit eigenem Zufallswert (Chiffrat etwa 4× so lang wie der Klartext). Verschlüsseln mit dem öffentlichen Schlüssel des Empfängers, entschlüsseln mit dem eigenen privaten Schlüssel.","Классическое шифрование ElGamal: параметры MODP Group 2 (1024 бита), открытый текст делится на блоки по 64 байта, для каждого — своё случайное значение (шифротекст примерно в 4 раза длиннее). Шифрование открытым ключом получателя, расшифрование своим закрытым."],
    "sm2-enc": ["国密 SM2 公钥加密（GM/T 0003-2012），sm2p256v1 曲线 + SM3 杂凑，密文格式为 C1||C3||C2（C1 为未压缩点，兼容旧版 C1||C2||C3）。加密用对方公钥，解密用自己的私钥。","國密 SM2 公鑰加密（GM/T 0003-2012），sm2p256v1 曲線 + SM3 雜湊，密文格式為 C1||C3||C2（C1 為未壓縮點，相容舊版 C1||C2||C3）。加密用對方公鑰，解密用自己的私鑰。","Chinese national SM2 public-key encryption (GM/T 0003-2012), sm2p256v1 curve + SM3 hash, ciphertext format C1||C3||C2 (C1 is an uncompressed point; also compatible with the older C1||C2||C3). Encrypt with the recipient's public key, decrypt with your own private key.","中国暗号 SM2 公開鍵暗号（GM/T 0003-2012）、sm2p256v1 曲線 + SM3 ハッシュ、暗号文形式は C1||C3||C2（C1 は非圧縮点、旧形式 C1||C2||C3 にも対応）。暗号化は相手の公開鍵、復号は自分の秘密鍵。","중국 국가암호 SM2 공개키 암호(GM/T 0003-2012), sm2p256v1 곡선 + SM3 해시, 암호문 형식 C1||C3||C2(C1은 비압축 점, 구버전 C1||C2||C3도 호환). 암호화는 상대 공개키, 복호화는 내 개인키.","Chiffrement à clé publique SM2 (norme chinoise GM/T 0003-2012), courbe sm2p256v1 + hachage SM3, format du chiffré C1||C3||C2 (C1 est un point non compressé ; compatible aussi avec l'ancien C1||C2||C3). Chiffrez avec la clé publique du destinataire, déchiffrez avec votre clé privée.","SM2-Verschlüsselung (chinesischer Standard GM/T 0003-2012), Kurve sm2p256v1 + Hash SM3, Chiffratformat C1||C3||C2 (C1 ist ein unkomprimierter Punkt; auch zum älteren C1||C2||C3 kompatibel). Verschlüsseln mit dem öffentlichen Schlüssel des Empfängers, entschlüsseln mit dem eigenen privaten Schlüssel.","Шифрование SM2 (китайский стандарт GM/T 0003-2012), кривая sm2p256v1 + хэш SM3, формат шифротекста C1||C3||C2 (C1 — несжатая точка, совместимо и со старым C1||C2||C3). Шифрование открытым ключом получателя, расшифрование своим закрытым."],
    "sm2-keyxchg": ["国密 SM2 密钥协商（GM/T 0003-2012 §6.1），两方各出一个临时随机数与临时点，协商出共享密钥。已与 gmalg（国密官方参考实现）交叉验证：5 组不同密钥长度与标识下双方密钥逐字节一致，并额外通过 4 组本地端到端协商。输出为协商出的共享密钥（默认 32 字节）。","國密 SM2 金鑰協商（GM/T 0003-2012 §6.1），兩方各出一個臨時隨機數與臨時點，協商出共享金鑰。已與 gmalg（國密官方參考實作）交叉驗證：5 組不同金鑰長度與標識下雙方金鑰逐位元組一致，並額外通過 4 組本地端到端協商。輸出為協商出的共享金鑰（預設 32 位元組）。","Chinese national SM2 key exchange (GM/T 0003-2012 §6.1): both parties contribute an ephemeral random value and ephemeral point to derive a shared key. Cross-verified against gmalg (the official reference implementation): byte-identical keys on both sides across 5 combinations of key length and identifier, plus 4 additional local end-to-end exchanges. Output is the derived shared key (32 bytes by default).","中国暗号 SM2 鍵共有（GM/T 0003-2012 §6.1）：両者が一時乱数と一時点を持ち寄り共有鍵を導出します。gmalg（公式リファレンス実装）と相互検証済み：鍵長と識別子の異なる 5 組で両者の鍵がバイト単位で一致、さらにローカル end-to-end 4 組も検証。出力は導出された共有鍵（既定 32 バイト）。","중국 국가암호 SM2 키 합의(GM/T 0003-2012 §6.1): 양측이 임시 난수와 임시 점을 제공해 공유키를 유도합니다. gmalg(공식 참조 구현)와 교차 검증: 키 길이와 식별자 조합 5건에서 양측 키가 바이트 단위로 일치, 추가로 로컬 end-to-end 4건 검증. 출력은 유도된 공유키(기본 32바이트).","Échange de clés SM2 (norme chinoise GM/T 0003-2012 §6.1) : chaque partie fournit une valeur aléatoire et un point éphémères pour dériver une clé partagée. Vérifié croisé avec gmalg (implémentation de référence officielle) : clés identiques à l'octet près sur 5 combinaisons de longueur de clé et d'identifiant, plus 4 échanges locaux de bout en bout. Sortie : la clé partagée dérivée (32 octets par défaut).","SM2-Schlüsselaustausch (chinesischer Standard GM/T 0003-2012 §6.1): beide Seiten steuern je einen ephemeren Zufallswert und Punkt bei, um einen gemeinsamen Schlüssel abzuleiten. Gegenreferenz mit gmalg (offizielle Referenzimplementierung): bytegleiche Schlüssel in 5 Kombinationen aus Schlüssellänge und Kennung, dazu 4 lokale Ende-zu-Ende-Austausche. Ausgabe ist der abgeleitete gemeinsame Schlüssel (standardmäßig 32 Bytes).","Выработка ключа SM2 (китайский стандарт GM/T 0003-2012 §6.1): обе стороны вносят эфемерное случайное значение и точку, получая общий ключ. Перекрёстно проверено с gmalg (официальная эталонная реализация): побайтовое совпадение в 5 комбинациях длины ключа и идентификатора, плюс 4 локальных сквозных обмена. Вывод — общий ключ (по умолчанию 32 байта)."],
    "sm9-sign": ["SM9 标识密码（GM/T 0044-2016）：用户的公钥就是他的身份标识（邮箱、ID），无需证书。KGC 用主私钥为 UID 生成签名私钥。已与 gmalg 交叉验证：私钥生成、签名 h/S、验签 45/45 一致。","SM9 標識密碼（GM/T 0044-2016）：使用者的公鑰就是他的身分標識（信箱、ID），無需憑證。KGC 用主私鑰為 UID 生成簽章私鑰。已與 gmalg 交叉驗證：私鑰生成、簽章 h/S、驗簽 45/45 一致。","SM9 identity-based cryptography (GM/T 0044-2016): a user's public key is simply their identifier (email, ID) — no certificate needed. The KGC derives a signing private key for the UID from the master private key. Cross-verified with gmalg: private key derivation, signature h/S, and verification all match 45/45.","SM9 ID ベース暗号（GM/T 0044-2016）：ユーザーの公開鍵はそのまま識別子（メールアドレスや ID）で、証明書は不要です。KGC はマスター秘密鍵から UID の署名秘密鍵を生成します。gmalg と相互検証済み：秘密鍵生成・署名 h/S・検証が 45/45 一致。","SM9 식별자 기반 암호(GM/T 0044-2016): 사용자의 공개키가 곧 식별자(이메일, ID)이며 인증서가 필요 없습니다. KGC는 마스터 개인키로 UID의 서명 개인키를 생성합니다. gmalg와 교차 검증: 개인키 생성, 서명 h/S, 검증이 45/45 일치.","Cryptographie basée sur l'identité SM9 (GM/T 0044-2016) : la clé publique d'un utilisateur est simplement son identifiant (e-mail, ID) — aucun certificat nécessaire. Le KGC dérive une clé privée de signature pour l'UID à partir de la clé maîtresse. Vérifié croisé avec gmalg : dérivation de clé, signature h/S et vérification concordent 45/45.","Identitätsbasierte Kryptografie SM9 (GM/T 0044-2016): der öffentliche Schlüssel eines Nutzers ist einfach seine Kennung (E-Mail, ID) — kein Zertifikat nötig. Das KGC leitet aus dem Hauptschlüssel einen Signaturschlüssel für die UID ab. Gegenreferenz mit gmalg: Schlüsselableitung, Signatur h/S und Prüfung stimmen 45/45 überein.","Криптография на основе идентификатора SM9 (GM/T 0044-2016): открытый ключ пользователя — это его идентификатор (e-mail, ID), сертификат не нужен. KGC выводит ключ подписи для UID из главного закрытого ключа. Перекрёстно проверено с gmalg: вывод ключа, подпись h/S и проверка совпадают 45/45."],
    "sm9-keygen-enc": ["SM9 标识加密（GM/T 0004-2016）的密钥生成。主公钥 mpk_e = [msk_e]P1 在 G1，用户加密私钥 de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 在 G2——与签名方向相反。输出三行：msk_e、mpk_e、de。已与 gmalg 官方库交叉验证私钥提取一致。","SM9 標識加密（GM/T 0004-2016）的金鑰生成。主公鑰 mpk_e = [msk_e]P1 在 G1，使用者加密私鑰 de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 在 G2——與簽章方向相反。輸出三行：msk_e、mpk_e、de。已與 gmalg 官方函式庫交叉驗證私鑰提取一致。","Key generation for SM9 identity-based encryption (GM/T 0004-2016). The master public key mpk_e = [msk_e]P1 lies in G1, while the user encryption private key de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 lies in G2 — the opposite of the signing direction. Three output lines: msk_e, mpk_e, de. Private key extraction cross-verified against the official gmalg library.","SM9 ID ベース暗号（GM/T 0004-2016）の鍵生成。マスター公開鍵 mpk_e = [msk_e]P1 は G1 上、ユーザー暗号化秘密鍵 de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 は G2 上——署名方向とは逆になります。出力は msk_e、mpk_e、de の 3 行。秘密鍵抽出は公式 gmalg ライブラリと相互検証済み。","SM9 식별자 기반 암호화(GM/T 0004-2016)의 키 생성. 마스터 공개키 mpk_e = [msk_e]P1은 G1, 사용자 암호화 개인키 de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2는 G2에 있습니다——서명 방향과 반대입니다. 출력은 msk_e, mpk_e, de 3줄. 개인키 추출은 공식 gmalg 라이브러리와 교차 검증.","Génération de clés pour le chiffrement basé sur l'identité SM9 (GM/T 0004-2016). La clé publique maîtresse mpk_e = [msk_e]P1 est dans G1, tandis que la clé privée de chiffrement de l'utilisateur de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 est dans G2 — l'inverse de la direction de signature. Trois lignes en sortie : msk_e, mpk_e, de. Extraction de clé privée vérifiée croisée avec la bibliothèque officielle gmalg.","Schlüsselerzeugung für identitätsbasierte Verschlüsselung SM9 (GM/T 0004-2016). Der Hauptschlüssel mpk_e = [msk_e]P1 liegt in G1, der Verschlüsselungsschlüssel des Nutzers de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 in G2 — entgegengesetzt zur Signaturrichtung. Drei Ausgabezeilen: msk_e, mpk_e, de. Schlüsselextraktion gegenreferenziert mit der offiziellen Bibliothek gmalg.","Генерация ключей для шифрования на основе идентификатора SM9 (GM/T 0004-2016). Главный открытый ключ mpk_e = [msk_e]P1 лежит в G1, а закрытый ключ шифрования de = [msk_e·(H1(ID‖3)+msk_e)^-1]P2 — в G2, то есть наоборот по сравнению с подписью. Три строки вывода: msk_e, mpk_e, de. Извлечение ключа перекрёстно проверено с официальной библиотекой gmalg."],
    "sm9-kem": ["SM9 标识加密的密钥封装：只需对方标识即可封装出一个共享密钥，无需证书。C = [r]Q（Q = [H1(ID‖3)]P1 + mpk_e），K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID)。已与 gmalg 官方库交叉验证封装与解封装逐字节一致。","SM9 標識加密的金鑰封裝：只需對方標識即可封裝出一個共享金鑰，無需憑證。C = [r]Q（Q = [H1(ID‖3)]P1 + mpk_e），K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID)。已與 gmalg 官方函式庫交叉驗證封裝與解封裝逐位元組一致。","Key encapsulation for SM9 identity-based encryption: a shared key can be encapsulated from the recipient's identifier alone — no certificate needed. C = [r]Q (Q = [H1(ID‖3)]P1 + mpk_e), K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID). Encapsulation and decapsulation cross-verified byte for byte against the official gmalg library.","SM9 ID ベース暗号の鍵カプセル化：相手の識別子だけで共有鍵をカプセル化でき、証明書は不要です。C = [r]Q（Q = [H1(ID‖3)]P1 + mpk_e）、K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID)。カプセル化と開封は公式 gmalg ライブラリとバイト単位で相互検証済み。","SM9 식별자 기반 암호화의 키 캡슐화: 상대 식별자만으로 공유키를 캡슐화할 수 있으며 인증서가 필요 없습니다. C = [r]Q(Q = [H1(ID‖3)]P1 + mpk_e), K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID). 캡슐화와 역캡슐화는 공식 gmalg 라이브러리와 바이트 단위로 교차 검증.","Encapsulation de clé pour le chiffrement basé sur l'identité SM9 : une clé partagée peut être encapsulée à partir du seul identifiant du destinataire — aucun certificat nécessaire. C = [r]Q (Q = [H1(ID‖3)]P1 + mpk_e), K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID). Encapsulation et décapsulation vérifiées octet par octet avec la bibliothèque officielle gmalg.","Schlüsselkapselung für identitätsbasierte Verschlüsselung SM9: ein gemeinsamer Schlüssel lässt sich allein aus der Kennung des Empfängers kapseln — kein Zertifikat nötig. C = [r]Q (Q = [H1(ID‖3)]P1 + mpk_e), K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID). Kapselung und Entkapselung byteweise gegenreferenziert mit der offiziellen Bibliothek gmalg.","Инкапсуляция ключа для шифрования на основе идентификатора SM9: общий ключ封装ляется только из идентификатора получателя, сертификат не нужен. C = [r]Q (Q = [H1(ID‖3)]P1 + mpk_e), K = SM3KDF(C.x‖C.y‖e(mpk_e,P2)^r‖ID). Инкапсуляция и раскапсуляция побайтово перекрёстно проверены с официальной библиотекой gmalg."],
    "sm9-enc": ["SM9 标识加密（GM/T 0004-2016）：公钥就是对方标识，无需证书。密文 = C1(65) ‖ C3(32, SM3 MAC) ‖ C2(与明文等长)。加密方只需主公钥，解密方持 KGC 签发的私钥。已与 gmalg 官方库交叉验证加解密逐字节一致；篡改密文必触发 MAC 校验失败。","SM9 標識加密（GM/T 0004-2016）：公鑰就是對方標識，無需憑證。密文 = C1(65) ‖ C3(32, SM3 MAC) ‖ C2(與明文等長)。加密方只需主公鑰，解密方持 KGC 簽發的私鑰。已與 gmalg 官方函式庫交叉驗證加解密逐位元組一致；篡改密文必觸發 MAC 校驗失敗。","SM9 identity-based encryption (GM/T 0004-2016): the public key is simply the recipient's identifier — no certificate needed. Ciphertext = C1(65) ‖ C3(32, SM3 MAC) ‖ C2(same length as plaintext). The sender needs only the master public key; the recipient holds a private key issued by the KGC. Cross-verified byte for byte against the official gmalg library; any tampering with the ciphertext always triggers MAC verification failure.","SM9 ID ベース暗号（GM/T 0004-2016）：公開鍵は相手の識別子そのもので、証明書は不要です。暗号文 = C1(65) ‖ C3(32, SM3 MAC) ‖ C2(平文と同じ長さ)。暗号化側はマスター公開鍵だけでよく、復号側は KGC が発行した秘密鍵を保持します。公式 gmalg ライブラリとバイト単位で相互検証済み。暗号文の改ざんは必ず MAC 検証失敗を引き起こします。","SM9 식별자 기반 암호화(GM/T 0004-2016): 공개키가 곧 상대 식별자이며 인증서가 필요 없습니다. 암호문 = C1(65) ‖ C3(32, SM3 MAC) ‖ C2(평문과 같은 길이). 암호화 측은 마스터 공개키만 필요하고, 복호화 측은 KGC가 발급한 개인키를 가집니다. 공식 gmalg 라이브러리와 바이트 단위로 교차 검증. 암호문 변조는 반드시 MAC 검증 실패를 유발합니다.","Chiffrement basé sur l'identité SM9 (GM/T 0004-2016) : la clé publique est simplement l'identifiant du destinataire — aucun certificat nécessaire. Chiffré = C1(65) ‖ C3(32, MAC SM3) ‖ C2(même longueur que le clair). L'expéditeur n'a besoin que de la clé publique maîtresse ; le destinataire détient une clé privée émise par le KGC. Vérifié octet par octet avec la bibliothèque officielle gmalg ; toute altération du chiffré provoque toujours l'échec de la vérification MAC.","Identitätsbasierte Verschlüsselung SM9 (GM/T 0004-2016): der öffentliche Schlüssel ist einfach die Kennung des Empfängers — kein Zertifikat nötig. Chiffrat = C1(65) ‖ C3(32, SM3-MAC) ‖ C2(gleich lang wie der Klartext). Der Sender braucht nur den Hauptschlüssel, der Empfänger hält einen vom KGC ausgestellten privaten Schlüssel. Byteweise gegenreferenziert mit der offiziellen Bibliothek gmalg; jede Manipulation des Chiffrats führt immer zum MAC-Fehler.","Шифрование на основе идентификатора SM9 (GM/T 0004-2016): открытый ключ — это идентификатор получателя, сертификат не нужен. Шифротекст = C1(65) ‖ C3(32, SM3 MAC) ‖ C2(той же длины, что открытый текст). Отправителю нужен только главный открытый ключ, получатель держит ключ, выданный KGC. Побайтово перекрёстно проверено с официальной библиотекой gmalg; любая подмена шифротекста всегда вызывает ошибку проверки MAC."],
    "frost": ["FROST（RFC 9591）两轮阈值签名：n 个参与者中任意 t 个合作才能签名，少于 t 个无法签名，全程不重建完整私钥，最终输出标准 Ed25519 签名。默认 t=2、n=3。份额用 nonce_generate 确定性派生（H3(随机数‖份额)），天然不存在随机数复用导致私钥泄露的风险。","FROST（RFC 9591）兩輪門檻簽章：n 個參與者中任意 t 個合作才能簽章，少於 t 個無法簽章，全程不重建完整私鑰，最終輸出標準 Ed25519 簽章。預設 t=2、n=3。份額用 nonce_generate 確定性派生（H3(隨機數‖份額)），天然不存在隨機數複用導致私鑰洩漏的風險。","FROST (RFC 9591) two-round threshold signature: any t of n participants can cooperate to sign, fewer than t cannot, the full private key is never reconstructed, and the output is a standard Ed25519 signature. Defaults t=2, n=3. Shares are derived deterministically via nonce_generate (H3(random‖share)), so there is inherently no risk of private key leakage from nonce reuse.","FROST（RFC 9591）2 ラウンド閾値署名：n 人の参加者のうち任意の t 人が協力すれば署名でき、t 人未満では不可能です。完全な秘密鍵を再構成することはなく、最終出力は標準の Ed25519 署名です。既定値は t=2、n=3。シェアは nonce_generate（H3(乱数‖シェア)）で決定的に導出されるため、nonce 再利用による秘密鍵漏洩のリスクは本質的にありません。","FROST(RFC 9591) 2라운드 임계값 서명: n명 중 임의의 t명이 협력하면 서명할 수 있고 t명 미만은 불가능하며, 전체 개인키를 재구성하지 않고 표준 Ed25519 서명을 출력합니다. 기본값 t=2, n=3. 셰어는 nonce_generate(H3(난수‖셰어))로 결정적으로 유도되어 nonce 재사용으로 인한 개인키 유출 위험이 본질적으로 없습니다.","FROST (RFC 9591), signature à seuil en deux tours : t participants quelconques parmi n peuvent coopérer pour signer, moins de t ne le peuvent pas, la clé privée complète n'est jamais reconstruite, et la sortie est une signature Ed25519 standard. Par défaut t=2, n=3. Les parts sont dérivées de façon déterministe via nonce_generate (H3(aléa‖part)), écartant par nature tout risque de fuite de clé par réutilisation de nonce.","FROST (RFC 9591), Schwellensignatur in zwei Runden: beliebige t von n Teilnehmern können gemeinsam signieren, weniger als t nicht, der vollständige private Schlüssel wird nie rekonstruiert, Ausgabe ist eine Standard-Ed25519-Signatur. Standard t=2, n=3. Anteile werden deterministisch über nonce_generate (H3(Zufall‖Anteil)) abgeleitet, daher besteht von Natur aus kein Risiko einer Schlüsselkompromittierung durch Nonce-Wiederverwendung.","FROST (RFC 9591) — пороговая подпись за два раунда: любые t из n участников могут подписать, менее t — нет, полный закрытый ключ никогда не восстанавливается, на выходе стандартная подпись Ed25519. По умолчанию t=2, n=3. Доли выводятся детерминированно через nonce_generate (H3(случайное‖доля)), поэтому риск утечки ключа из-за повторного использования nonce отсутствует по своей природе."],
    "gg20": ["GG20（Gennaro & Goldfeder, ACM CCS 2020）阈值 ECDSA：t 个参与者合作产生标准 ECDSA 签名，全程不重建私钥。核心为 Paillier 同态加密 + MtA 乘法转加法。默认 t=2、n=3。⚠️ 本实现只含协议算术核心，未实现论文中的零知识证明，存在 Alpha-Rays（2023）类攻击面，仅用于学习与协议演示。","GG20（Gennaro & Goldfeder, ACM CCS 2020）門檻 ECDSA：t 個參與者合作產生標準 ECDSA 簽章，全程不重建私鑰。核心為 Paillier 同態加密 + MtA 乘法轉加法。預設 t=2、n=3。⚠️ 本實作只含協議算術核心，未實作論文中的零知識證明，存在 Alpha-Rays（2023）類攻擊面，僅用於學習與協議演示。","GG20 (Gennaro & Goldfeder, ACM CCS 2020) threshold ECDSA: t participants cooperate to produce a standard ECDSA signature without ever reconstructing the private key. Core is Paillier homomorphic encryption + MtA (multiplication-to-addition). Defaults t=2, n=3. ⚠️ This implementation contains only the protocol arithmetic core and not the zero-knowledge proofs from the paper, so it is exposed to Alpha-Rays (2023)-class attacks — for study and protocol demonstration only.","GG20（Gennaro & Goldfeder, ACM CCS 2020）閾値 ECDSA：t 人の参加者が協力して標準 ECDSA 署名を生成し、秘密鍵を再構成しません。中核は Paillier 準同型暗号 + MtA（乗算から加算への変換）です。既定値は t=2、n=3。⚠️ 本実装はプロトコルの算術中核のみで、論文のゼロ知識証明は未実装のため Alpha-Rays（2023）系の攻撃面が残ります。学習・デモ専用です。","GG20(Gennaro & Goldfeder, ACM CCS 2020) 임계값 ECDSA: t명이 협력해 표준 ECDSA 서명을 만들며 개인키를 재구성하지 않습니다. 핵심은 Paillier 동형암호 + MtA(곱셈→덧셈 변환). 기본값 t=2, n=3. ⚠️ 이 구현은 프로토콜 산술 핵심만 포함하며 논문의 영지식 증명은 미구현이므로 Alpha-Rays(2023) 계열 공격면이 남습니다. 학습·데모 전용.","GG20 (Gennaro & Goldfeder, ACM CCS 2020), ECDSA à seuil : t participants coopèrent pour produire une signature ECDSA standard sans jamais reconstruire la clé privée. Le cœur est le chiffrement homomorphe de Paillier + MtA (multiplication vers addition). Par défaut t=2, n=3. ⚠️ Cette implémentation ne contient que le cœur arithmétique du protocole, sans les preuves à divulgation nulle de connaissance de l'article ; elle reste exposée aux attaques de type Alpha-Rays (2023) — pour l'étude et la démonstration uniquement.","GG20 (Gennaro & Goldfeder, ACM CCS 2020), Schwellen-ECDSA: t Teilnehmer erzeugen gemeinsam eine Standard-ECDSA-Signatur, ohne den privaten Schlüssel zu rekonstruieren. Kern sind die homomorphe Paillier-Verschlüsselung + MtA (Multiplikation zu Addition). Standard t=2, n=3. ⚠️ Diese Implementierung enthält nur den arithmetischen Kern des Protokolls, nicht die Zero-Knowledge-Beweise aus dem Paper, und bleibt damit für Alpha-Rays (2023)-artige Angriffe offen — nur zum Lernen und zur Demonstration.","GG20 (Gennaro & Goldfeder, ACM CCS 2020) — пороговый ECDSA: t участников совместно создают стандартную подпись ECDSA, не восстанавливая закрытый ключ. В основе — гомоморфное шифрование Paillier + MtA (преобразование умножения в сложение). По умолчанию t=2, n=3. ⚠️ Реализация содержит только арифметическое ядро протокола без доказательств с нулевым разглашением из статьи, поэтому остаётся уязвимой для атак класса Alpha-Rays (2023) — только для обучения и демонстрации."],
    "hpke": ["HPKE 风格：X25519 ECDH → HKDF-SHA256 → AES-256-GCM。加密需填对方公钥，输出「临时公钥‖nonce‖密文+tag」；解密填自己的私钥，密文里自带临时公钥，无需额外参数。","HPKE 風格：X25519 ECDH → HKDF-SHA256 → AES-256-GCM。加密需填對方公鑰，輸出「臨時公鑰‖nonce‖密文+tag」；解密填自己的私鑰，密文裡自帶臨時公鑰，無需額外參數。","HPKE-style: X25519 ECDH → HKDF-SHA256 → AES-256-GCM. For encryption enter the recipient's public key; output is \"ephemeral public key‖nonce‖ciphertext+tag\". For decryption enter your own private key — the ephemeral public key is carried in the ciphertext, so no extra parameters are needed.","HPKE 方式：X25519 ECDH → HKDF-SHA256 → AES-256-GCM。暗号化には相手の公開鍵を入力し、「一時公開鍵‖nonce‖暗号文+tag」を出力します。復号には自分の秘密鍵を入力します。一時公開鍵は暗号文に含まれるため追加パラメータは不要です。","HPKE 방식: X25519 ECDH → HKDF-SHA256 → AES-256-GCM. 암호화에는 상대 공개키를 입력하고 \"임시 공개키‖nonce‖암호문+tag\"를 출력합니다. 복호화에는 내 개인키를 입력합니다. 임시 공개키가 암호문에 포함되므로 추가 파라미터가 필요 없습니다.","Style HPKE : X25519 ECDH → HKDF-SHA256 → AES-256-GCM. Pour chiffrer, saisissez la clé publique du destinataire ; la sortie est « clé publique éphémère‖nonce‖chiffré+tag ». Pour déchiffrer, saisissez votre clé privée — la clé publique éphémère est incluse dans le chiffré, aucun paramètre supplémentaire n'est nécessaire.","HPKE-artig: X25519 ECDH → HKDF-SHA256 → AES-256-GCM. Zum Verschlüsseln den öffentlichen Schlüssel des Empfängers eingeben; Ausgabe ist „ephemerer öffentlicher Schlüssel‖nonce‖Chiffrat+tag\". Zum Entschlüsseln den eigenen privaten Schlüssel eingeben — der ephemeren öffentliche Schlüssel steckt im Chiffrat, weitere Parameter sind nicht nötig.","В стиле HPKE: X25519 ECDH → HKDF-SHA256 → AES-256-GCM. Для шифрования укажите открытый ключ получателя, вывод: «эфемерный открытый ключ‖nonce‖шифротекст+tag». Для расшифрования — свой закрытый ключ; эфемерный открытый ключ содержится в шифротексте, дополнительные параметры не нужны."],
    "spake2p-register": ["把口令转为 SPAKE2+ 注册记录：输出 w0/L（给服务器）与 w1（给客户端）。服务器不存明文口令。","把口令轉為 SPAKE2+ 註冊記錄：輸出 w0/L（給伺服器）與 w1（給客戶端）。伺服器不存明文口令。","Turn a password into a SPAKE2+ registration record: outputs w0/L (for the server) and w1 (for the client). The server never stores the plaintext password.","パスワードを SPAKE2+ の登録レコードに変換します：w0/L（サーバー向け）と w1（クライアント向け）を出力します。サーバーは平文パスワードを保存しません。","비밀번호를 SPAKE2+ 등록 레코드로 변환: w0/L(서버용)과 w1(클라이언트용)을 출력합니다. 서버는 평문 비밀번호를 저장하지 않습니다.","Convertit un mot de passe en enregistrement SPAKE2+ : sortie w0/L (pour le serveur) et w1 (pour le client). Le serveur ne stocke jamais le mot de passe en clair.","Wandelt ein Passwort in einen SPAKE2+-Registrierungsdatensatz um: Ausgabe w0/L (für den Server) und w1 (für den Client). Der Server speichert das Passwort nie im Klartext.","Преобразует пароль в регистрационную запись SPAKE2+: вывод w0/L (для сервера) и w1 (для клиента). Сервер не хранит пароль в открытом виде."],
    "spake2p-prover": ["SPAKE2+ 客户端。填 w0/w1/x 与对方 share，得到 K_shared。⚠ RFC 9383 未规定 PBKDF 选择，注册条目的 PBKDF2 仅供演示。","SPAKE2+ 客戶端。填 w0/w1/x 與對方 share，得到 K_shared。⚠ RFC 9383 未規定 PBKDF 選擇，註冊條目的 PBKDF2 僅供演示。","SPAKE2+ client. Fill in w0/w1/x and the peer's share to obtain K_shared. ⚠ RFC 9383 does not specify the PBKDF choice; the PBKDF2 used by the registration entry is for demonstration only.","SPAKE2+ クライアント。w0/w1/x と相手の share を入力すると K_shared が得られます。⚠ RFC 9383 は PBKDF の選択を規定していないため、登録エントリの PBKDF2 はデモ用です。","SPAKE2+ 클라이언트. w0/w1/x와 상대 share를 입력하면 K_shared를 얻습니다. ⚠ RFC 9383은 PBKDF 선택을 규정하지 않으므로 등록 항목의 PBKDF2는 데모용입니다.","Client SPAKE2+. Renseignez w0/w1/x et la part de l'homologue pour obtenir K_shared. ⚠ La RFC 9383 ne spécifie pas le choix de PBKDF ; le PBKDF2 de l'entrée d'enregistrement n'est qu'une démonstration.","SPAKE2+-Client. w0/w1/x und den Anteil der Gegenseite eingeben, um K_shared zu erhalten. ⚠ RFC 9383 legt die PBKDF-Wahl nicht fest; das PBKDF2 des Registrierungseintrags dient nur der Demonstration.","Клиент SPAKE2+. Укажите w0/w1/x и долю другой стороны, чтобы получить K_shared. ⚠ RFC 9383 не определяет выбор PBKDF; PBKDF2 в записи регистрации приведён только для демонстрации."],
    "spake2p-verifier": ["SPAKE2+ 服务端。填 w0/L/y 与对方 share，得到 K_shared。需与客户端结果一致才算协商成功。","SPAKE2+ 服務端。填 w0/L/y 與對方 share，得到 K_shared。需與客戶端結果一致才算協商成功。","SPAKE2+ server. Fill in w0/L/y and the peer's share to obtain K_shared. It must match the client's result for the exchange to succeed.","SPAKE2+ サーバー。w0/L/y と相手の share を入力すると K_shared が得られます。クライアントの結果と一致して初めてネゴシエーション成功です。","SPAKE2+ 서버. w0/L/y와 상대 share를 입력하면 K_shared를 얻습니다. 클라이언트 결과와 일치해야 합의가 성공합니다.","Serveur SPAKE2+. Renseignez w0/L/y et la part de l'homologue pour obtenir K_shared. La valeur doit correspondre à celle du client pour que l'échange réussisse.","SPAKE2+-Server. w0/L/y und den Anteil der Gegenseite eingeben, um K_shared zu erhalten. Der Wert muss mit dem des Clients übereinstimmen, damit der Austausch gelingt.","Сервер SPAKE2+. Укажите w0/L/y и долю другой стороны, чтобы получить K_shared. Значение должно совпасть с клиентским — только тогда обмен считается успешным."],
    "ed25519-ctx": ["RFC 8032 的 Ed25519 变体。ctx = 带应用上下文字符串，防止跨场景签名重用。与纯 Ed25519 的区别只在 dom2 前缀与 PH(M)。签名 64 字节。","RFC 8032 的 Ed25519 變體。ctx = 帶應用上下文字串，防止跨場景簽章重用。與純 Ed25519 的區別只在 dom2 前綴與 PH(M)。簽章 64 位元組。","An Ed25519 variant from RFC 8032. ctx = carries an application context string to prevent signature reuse across contexts. Differs from pure Ed25519 only in the dom2 prefix and PH(M). Signature is 64 bytes.","RFC 8032 の Ed25519 変種。ctx = アプリケーションコンテキスト文字列を持ち、場面をまたいだ署名の流用を防ぎます。純粋な Ed25519 との違いは dom2 プレフィックスと PH(M) のみです。署名は 64 バイト。","RFC 8032의 Ed25519 변형. ctx = 애플리케이션 컨텍스트 문자열을 포함해 상황 간 서명 재사용을 방지합니다. 순수 Ed25519와의 차이는 dom2 접두사와 PH(M)뿐입니다. 서명은 64바이트.","Une variante d'Ed25519 de la RFC 8032. ctx = porte une chaîne de contexte applicatif pour empêcher la réutilisation de signatures entre contextes. Ne diffère d'Ed25519 pur que par le préfixe dom2 et PH(M). Signature de 64 octets.","Eine Ed25519-Variante aus RFC 8032. ctx = trägt eine Anwendungskontext-Zeichenkette, um signaturübergreifende Wiederverwendung zu verhindern. Unterscheidet sich von reinem Ed25519 nur im dom2-Präfix und in PH(M). Signatur: 64 Bytes.","Вариант Ed25519 из RFC 8032. ctx = несёт строку контекста приложения, чтобы подпись нельзя было перенести в другой сценарий. Отличается от чистого Ed25519 только префиксом dom2 и PH(M). Подпись — 64 байта."],
    "ed25519-ph": ["RFC 8032 的 Ed25519 变体。ph = 先对消息做 SHA-512 再签名，适合超大消息或流式签名（libsodium 官方实现交叉验证 24/24）。与纯 Ed25519 的区别只在 dom2 前缀与 PH(M)。签名 64 字节。","RFC 8032 的 Ed25519 變體。ph = 先對訊息做 SHA-512 再簽章，適合超大訊息或串流簽章（libsodium 官方實作交叉驗證 24/24）。與純 Ed25519 的區別只在 dom2 前綴與 PH(M)。簽章 64 位元組。","An Ed25519 variant from RFC 8032. ph = hash the message with SHA-512 before signing, suitable for very large messages or streaming signatures (cross-verified 24/24 against the official libsodium implementation). Differs from pure Ed25519 only in the dom2 prefix and PH(M). Signature is 64 bytes.","RFC 8032 の Ed25519 変種。ph = メッセージを SHA-512 でハッシュしてから署名するため、巨大なメッセージやストリーミング署名に適しています（libsodium 公式実装と 24/24 で相互検証）。純粋な Ed25519 との違いは dom2 プレフィックスと PH(M) のみ。署名は 64 バイト。","RFC 8032의 Ed25519 변형. ph = 메시지를 SHA-512로 해시한 뒤 서명하므로 매우 큰 메시지나 스트리밍 서명에 적합합니다(libsodium 공식 구현과 24/24 교차 검증). 순수 Ed25519와의 차이는 dom2 접두사와 PH(M)뿐. 서명은 64바이트.","Une variante d'Ed25519 de la RFC 8032. ph = la message est haché avec SHA-512 avant signature, adapté aux très gros messages ou à la signature en flux (vérifié croisé 24/24 avec l'implémentation officielle libsodium). Ne diffère d'Ed25519 pur que par le préfixe dom2 et PH(M). Signature de 64 octets.","Eine Ed25519-Variante aus RFC 8032. ph = die Nachricht wird vor dem Signieren mit SHA-512 gehasht, geeignet für sehr große Nachrichten oder Streaming-Signaturen (24/24 gegenreferenziert mit der offiziellen libsodium-Implementierung). Unterscheidet sich von reinem Ed25519 nur im dom2-Präfix und in PH(M). Signatur: 64 Bytes.","Вариант Ed25519 из RFC 8032. ph = сообщение сначала хэшируется SHA-512, подходит для очень больших сообщений или потоковой подписи (перекрёстно проверено 24/24 с официальной реализацией libsodium). Отличается от чистого Ed25519 только префиксом dom2 и PH(M). Подпись — 64 байта."],
    "ristretto255-dh": ["Ristretto255 上的 Diffie-Hellman：己方标量 a × 对方点 Q = 共享点。相比 X25519 无需\"清除余因子\"步骤，因为 Ristretto255 本身就是素数阶群。加密与解密同一操作。","Ristretto255 上的 Diffie-Hellman：己方純量 a × 對方點 Q = 共享點。相比 X25519 無需「清除餘因子」步驟，因為 Ristretto255 本身就是素數階群。加密與解密同一操作。","Diffie-Hellman over Ristretto255: own scalar a × peer point Q = shared point. Unlike X25519, no \"cofactor clearing\" step is needed because Ristretto255 is itself a prime-order group. Encryption and decryption are the same operation.","Ristretto255 上の Diffie-Hellman：自分のスカラー a × 相手の点 Q = 共有点。X25519 と異なり「余因子のクリア」は不要です。Ristretto255 自体が素数位数の群だからです。暗号化と復号は同じ操作です。","Ristretto255 상의 Diffie-Hellman: 내 스칼라 a × 상대 점 Q = 공유 점. Ristretto255 자체가 소수 차수 군이므로 X25519와 달리 \"여인자 제거\" 단계가 필요 없습니다. 암호화와 복호화는 동일한 작업입니다.","Diffie-Hellman sur Ristretto255 : scalaire propre a × point Q de l'homologue = point partagé. Contrairement à X25519, aucune étape de « nettoyage du cofacteur » n'est nécessaire car Ristretto255 est déjà un groupe d'ordre premier. Chiffrement et déchiffrement sont une même opération.","Diffie-Hellman über Ristretto255: eigener Skalar a × Punkt Q der Gegenseite = gemeinsamer Punkt. Anders als bei X25519 ist kein „Cofactor-Clearing\" nötig, da Ristretto255 bereits eine Gruppe von Primordnung ist. Ver- und Entschlüsseln sind dieselbe Operation.","Diffie-Hellman на Ristretto255: свой скаляр a × точка Q другой стороны = общая точка. В отличие от X25519, шаг «очистки кофактора» не нужен, так как Ristretto255 уже является группой простого порядка. Шифрование и расшифрование — одна операция."],
    "decaf448-dh": ["Decaf448 上的 Diffie-Hellman：己方标量 a × 对方点 Q。群本身是素数阶，无需额外\"清除余因子\"步骤。加密与解密同一操作。","Decaf448 上的 Diffie-Hellman：己方純量 a × 對方點 Q。群本身是素數階，無需額外「清除餘因子」步驟。加密與解密同一操作。","Diffie-Hellman over Decaf448: own scalar a × peer point Q. The group itself is prime-order, so no extra \"cofactor clearing\" step is needed. Encryption and decryption are the same operation.","Decaf448 上の Diffie-Hellman：自分のスカラー a × 相手の点 Q。群自体が素数位数なので、追加の「余因子のクリア」は不要です。暗号化と復号は同じ操作です。","Decaf448 상의 Diffie-Hellman: 내 스칼라 a × 상대 점 Q. 군 자체가 소수 차수이므로 추가 \"여인자 제거\" 단계가 필요 없습니다. 암호화와 복호화는 동일한 작업입니다.","Diffie-Hellman sur Decaf448 : scalaire propre a × point Q de l'homologue. Le groupe est d'ordre premier, aucune étape supplémentaire de « nettoyage du cofacteur » n'est nécessaire. Chiffrement et déchiffrement sont une même opération.","Diffie-Hellman über Decaf448: eigener Skalar a × Punkt Q der Gegenseite. Die Gruppe hat Primordnung, ein zusätzliches „Cofactor-Clearing\" ist nicht nötig. Ver- und Entschlüsseln sind dieselbe Operation.","Diffie-Hellman на Decaf448: свой скаляр a × точка Q другой стороны. Группа имеет простой порядок, дополнительная «очистка кофактора» не требуется. Шифрование и расшифрование — одна операция."],
    "ibe-setup": ["Boneh-Franklin 基于身份加密的主密钥建立。输出主私钥 s（必须离线保管）与公开参数 Ppub = s·P₂（可公开）。之后任何身份的私钥都由 s 派生。","Boneh-Franklin 基於身分加密的主金鑰建立。輸出主私鑰 s（必須離線保管）與公開參數 Ppub = s·P₂（可公開）。之後任何身分的私鑰都由 s 派生。","Master key setup for Boneh-Franklin identity-based encryption. Outputs the master private key s (must be kept offline) and the public parameter Ppub = s·P₂ (may be published). Private keys for any identity are later derived from s.","Boneh-Franklin ID ベース暗号のマスター鍵セットアップ。マスター秘密鍵 s（オフラインで保管必須）と公開パラメータ Ppub = s·P₂（公開可）を出力します。以降、任意の ID の秘密鍵は s から導出されます。","Boneh-Franklin 식별자 기반 암호화의 마스터 키 설정. 마스터 개인키 s(오프라인 보관 필수)와 공개 파라미터 Ppub = s·P₂(공개 가능)를 출력합니다. 이후 모든 식별자의 개인키는 s에서 유도됩니다.","Établissement de la clé maîtresse pour le chiffrement basé sur l'identité de Boneh-Franklin. Sortie : la clé privée maîtresse s (à conserver hors ligne) et le paramètre public Ppub = s·P₂ (publiable). Les clés privées de toute identité sont ensuite dérivées de s.","Einrichtung des Hauptschlüssels für identitätsbasierte Verschlüsselung nach Boneh-Franklin. Ausgabe: der Haupt-Geheimschlüssel s (muss offline aufbewahrt werden) und der öffentliche Parameter Ppub = s·P₂ (veröffentlichbar). Alle Identitätsschlüssel werden danach aus s abgeleitet.","Создание главного ключа для шифрования на основе идентификатора Boneh-Franklin. Вывод: главный закрытый ключ s (хранить офлайн) и открытый параметр Ppub = s·P₂ (можно публиковать). Закрытые ключи любых идентификаторов затем выводятся из s."],
    "ibe-extract": ["用主私钥为某个身份派生私钥 d_ID = s·H₁(ID) ∈ G1。身份可以是邮箱、手机号等任意字符串——这正是 IBE 无需证书的原因。输出 64 字节 G1 点。","用主私鑰為某個身分派生私鑰 d_ID = s·H₁(ID) ∈ G1。身分可以是信箱、手機號等任意字串——這正是 IBE 無需憑證的原因。輸出 64 位元組 G1 點。","Derive the private key for an identity from the master private key: d_ID = s·H₁(ID) ∈ G1. The identity can be any string — an email, a phone number — which is exactly why IBE needs no certificates. Output is a 64-byte G1 point.","マスター秘密鍵から特定 ID の秘密鍵 d_ID = s·H₁(ID) ∈ G1 を導出します。ID はメールアドレスや電話番号など任意の文字列でよく、これが IBE に証明書が不要な理由です。出力は 64 バイトの G1 点です。","마스터 개인키로 특정 식별자의 개인키 d_ID = s·H₁(ID) ∈ G1을 유도합니다. 식별자는 이메일, 전화번호 등 임의의 문자열이 될 수 있으며, 이것이 IBE에 인증서가 필요 없는 이유입니다. 출력은 64바이트 G1 점입니다.","Dérive la clé privée d'une identité depuis la clé maîtresse : d_ID = s·H₁(ID) ∈ G1. L'identité peut être n'importe quelle chaîne — e-mail, numéro de téléphone — c'est précisément pourquoi l'IBE n'a pas besoin de certificats. Sortie : un point G1 de 64 octets.","Leitet aus dem Hauptschlüssel den Schlüssel einer Identität ab: d_ID = s·H₁(ID) ∈ G1. Die Identität kann eine beliebige Zeichenkette sein — E-Mail, Telefonnummer —, genau deshalb braucht IBE keine Zertifikate. Ausgabe ist ein 64-Byte-G1-Punkt.","Вывод закрытого ключа для идентификатора из главного ключа: d_ID = s·H₁(ID) ∈ G1. Идентификатором может быть любая строка — e-mail, номер телефона —, именно поэтому IBE не нужны сертификаты. Вывод — точка G1 длиной 64 байта."],
    "ibe-encrypt": ["Boneh-Franklin IBE 加密。无需对方证书，只要知道身份字符串即可加密。密文 = U(r·P₂，128 字节) ‖ 密文主体。⚠ BF-IBE 只能加密短消息（此处用 XOR 流），实际应封装一个对称密钥。","Boneh-Franklin IBE 加密。無需對方憑證，只要知道身分字串即可加密。密文 = U(r·P₂，128 位元組) ‖ 密文主體。⚠ BF-IBE 只能加密短訊息（此處用 XOR 流），實際應封裝一個對稱金鑰。","Boneh-Franklin IBE encryption. No certificate from the recipient is needed — knowing the identity string is enough. Ciphertext = U(r·P₂, 128 bytes) ‖ ciphertext body. ⚠ BF-IBE can only encrypt short messages (an XOR stream is used here); in practice it should encapsulate a symmetric key.","Boneh-Franklin IBE 暗号化。相手の証明書は不要で、ID 文字列が分かれば暗号化できます。暗号文 = U(r·P₂、128 バイト) ‖ 暗号文本体。⚠ BF-IBE は短いメッセージしか暗号化できません（ここでは XOR ストリームを使用）。実際には対称鍵をカプセル化すべきです。","Boneh-Franklin IBE 암호화. 상대 인증서가 필요 없고 식별자 문자열만 알면 암호화할 수 있습니다. 암호문 = U(r·P₂, 128바이트) ‖ 암호문 본문. ⚠ BF-IBE는 짧은 메시지만 암호화할 수 있습니다(여기서는 XOR 스트림 사용). 실제로는 대칭키를 캡슐화해야 합니다.","Chiffrement IBE de Boneh-Franklin. Aucun certificat du destinataire n'est nécessaire : connaître la chaîne d'identité suffit. Chiffré = U(r·P₂, 128 octets) ‖ corps du chiffré. ⚠ BF-IBE ne peut chiffrer que des messages courts (un flux XOR est utilisé ici) ; en pratique il faut encapsuler une clé symétrique.","Boneh-Franklin-IBE-Verschlüsselung. Kein Zertifikat des Empfängers nötig — die Kennung als Zeichenkette genügt. Chiffrat = U(r·P₂, 128 Bytes) ‖ Chiffratkörper. ⚠ BF-IBE kann nur kurze Nachrichten verschlüsseln (hier ein XOR-Strom); in der Praxis sollte ein symmetrischer Schlüssel gekapselt werden.","Шифрование IBE по Boneh-Franklin. Сертификат получателя не нужен — достаточно строки идентификатора. Шифротекст = U(r·P₂, 128 байт) ‖ тело шифротекста. ⚠ BF-IBE шифрует только короткие сообщения (здесь используется XOR-поток); на практике следует инкапсулировать симметричный ключ."],
    "ibe-decrypt": ["用 IBE 用户私钥解密。取密文头 128 字节作为 U，计算 e(d_ID, U) 还原掩码。若身份不匹配，解出来是乱码而非报错——这是 IBE 的常见特性。","用 IBE 使用者私鑰解密。取密文頭 128 位元組作為 U，計算 e(d_ID, U) 還原掩碼。若身分不匹配，解出來是亂碼而非報錯——這是 IBE 的常見特性。","Decrypt with the IBE user private key. Take the first 128 bytes of the ciphertext as U and compute e(d_ID, U) to recover the mask. If the identity does not match, the result is garbage rather than an error — a common characteristic of IBE.","IBE ユーザー秘密鍵で復号します。暗号文の先頭 128 バイトを U として e(d_ID, U) を計算しマスクを復元します。ID が一致しない場合はエラーではなく文字化けになります——IBE の一般的な特性です。","IBE 사용자 개인키로 복호화합니다. 암호문 앞 128바이트를 U로 삼아 e(d_ID, U)를 계산해 마스크를 복원합니다. 식별자가 일치하지 않으면 오류가 아닌 깨진 문자열이 나옵니다——IBE의 흔한 특성입니다.","Déchiffrement avec la clé privée IBE de l'utilisateur. Les 128 premiers octets du chiffré sont pris comme U et e(d_ID, U) est calculé pour retrouver le masque. Si l'identité ne correspond pas, on obtient du bruit plutôt qu'une erreur — une caractéristique courante de l'IBE.","Entschlüsseln mit dem IBE-Nutzerschlüssel. Die ersten 128 Bytes des Chiffrats werden als U genommen und e(d_ID, U) berechnet, um die Maske zu gewinnen. Passt die Identität nicht, entsteht Datenmüll statt einer Fehlermeldung — eine übliche Eigenart von IBE.","Расшифрование закрытым ключом пользователя IBE. Первые 128 байт шифротекста берутся как U, вычисляется e(d_ID, U) для восстановления маски. Если идентификатор не совпадает, получается мусор, а не ошибка — обычная особенность IBE."],
    "rsa-kem-encaps": ["RSA-KEM 封装：C0 = R^E mod N，共享密钥 K = KDF(R)。\n【关键】KDF 输入是明文 R 而非密文 C0。\n【验证】Botan pubkey/rsa_kem.vec 官方向量 10/10（KDF1-18033/KDF2 × SHA-1/256/512）。\n【输出】前 N 字节为 C0，其后为 K。","RSA-KEM 封裝：C0 = R^E mod N，共享金鑰 K = KDF(R)。\n【關鍵】KDF 輸入是明文 R 而非密文 C0。\n【驗證】Botan pubkey/rsa_kem.vec 官方向量 10/10（KDF1-18033/KDF2 × SHA-1/256/512）。\n【輸出】前 N 位元組為 C0，其後為 K。","RSA-KEM encapsulation: C0 = R^E mod N, shared key K = KDF(R).\n[Key point] The KDF input is the plaintext R, not the ciphertext C0.\n[Verified] Botan pubkey/rsa_kem.vec official vectors 10/10 (KDF1-18033/KDF2 × SHA-1/256/512).\n[Output] The first N bytes are C0, followed by K.","RSA-KEM カプセル化：C0 = R^E mod N、共有鍵 K = KDF(R)。\n【重要】KDF の入力は暗号文 C0 ではなく平文 R です。\n【検証】Botan pubkey/rsa_kem.vec 公式ベクトル 10/10（KDF1-18033/KDF2 × SHA-1/256/512）。\n【出力】先頭 N バイトが C0、その後が K です。","RSA-KEM 캡슐화: C0 = R^E mod N, 공유키 K = KDF(R).\n【핵심】KDF 입력은 암호문 C0이 아닌 평문 R입니다.\n【검증】Botan pubkey/rsa_kem.vec 공식 벡터 10/10(KDF1-18033/KDF2 × SHA-1/256/512).\n【출력】앞 N바이트가 C0, 그 뒤가 K입니다.","Encapsulation RSA-KEM : C0 = R^E mod N, clé partagée K = KDF(R).\n[Point clé] L'entrée du KDF est le clair R, non le chiffré C0.\n[Vérifié] Vecteurs officiels Botan pubkey/rsa_kem.vec 10/10 (KDF1-18033/KDF2 × SHA-1/256/512).\n[Sortie] Les N premiers octets sont C0, suivis de K.","RSA-KEM-Kapselung: C0 = R^E mod N, gemeinsamer Schlüssel K = KDF(R).\n[Kernpunkt] Der KDF-Eingang ist der Klartext R, nicht das Chiffrat C0.\n[Verifiziert] Offizielle Botan-Vektoren pubkey/rsa_kem.vec 10/10 (KDF1-18033/KDF2 × SHA-1/256/512).\n[Ausgabe] Die ersten N Bytes sind C0, danach folgt K.","Инкапсуляция RSA-KEM: C0 = R^E mod N, общий ключ K = KDF(R).\n[Ключевой момент] На вход KDF подаётся открытый текст R, а не шифротекст C0.\n[Проверено] Официальные векторы Botan pubkey/rsa_kem.vec 10/10 (KDF1-18033/KDF2 × SHA-1/256/512).\n[Вывод] Первые N байт — C0, далее K."],
    "rsa-kem-decaps": ["RSA-KEM 解封装：由 C0 还原 R = C0^D mod N，再算 K = KDF(R)。\n【验证】Botan pubkey/rsa_kem.vec 官方向量 10/10。\n【输出】前 N 字节为 R，其后为 K。","RSA-KEM 解封裝：由 C0 還原 R = C0^D mod N，再算 K = KDF(R)。\n【驗證】Botan pubkey/rsa_kem.vec 官方向量 10/10。\n【輸出】前 N 位元組為 R，其後為 K。","RSA-KEM decapsulation: recover R = C0^D mod N from C0, then compute K = KDF(R).\n[Verified] Botan pubkey/rsa_kem.vec official vectors 10/10.\n[Output] The first N bytes are R, followed by K.","RSA-KEM 開封：C0 から R = C0^D mod N を復元し、K = KDF(R) を計算します。\n【検証】Botan pubkey/rsa_kem.vec 公式ベクトル 10/10。\n【出力】先頭 N バイトが R、その後が K です。","RSA-KEM 역캡슐화: C0에서 R = C0^D mod N을 복원한 뒤 K = KDF(R)를 계산합니다.\n【검증】Botan pubkey/rsa_kem.vec 공식 벡터 10/10.\n【출력】앞 N바이트가 R, 그 뒤가 K입니다.","Décapsulation RSA-KEM : on retrouve R = C0^D mod N à partir de C0, puis K = KDF(R).\n[Vérifié] Vecteurs officiels Botan pubkey/rsa_kem.vec 10/10.\n[Sortie] Les N premiers octets sont R, suivis de K.","RSA-KEM-Entkapselung: aus C0 wird R = C0^D mod N gewonnen, dann K = KDF(R) berechnet.\n[Verifiziert] Offizielle Botan-Vektoren pubkey/rsa_kem.vec 10/10.\n[Ausgabe] Die ersten N Bytes sind R, danach folgt K.","Раскапсуляция RSA-KEM: из C0 восстанавливается R = C0^D mod N, затем вычисляется K = KDF(R).\n[Проверено] Официальные векторы Botan pubkey/rsa_kem.vec 10/10.\n[Вывод] Первые N байт — R, далее K."],
    "srp6a": ["SRP-6a：服务端只存验证子 v=g^x，口令不上网不落库。输出 v/A/B/S 四行。默认 1024 位群（RFC 5054 附录 A），3072 位及以上 g=5，群参数取自官方向量未手抄。Botan 向量 6 群×5 哈希逐项一致。仅用于验证教学，真实协议还需 M1/M2 且须走 TLS。","SRP-6a：服務端只存驗證子 v=g^x，口令不上網不落庫。輸出 v/A/B/S 四行。預設 1024 位元群（RFC 5054 附錄 A），3072 位及以上 g=5，群參數取自官方向量未手抄。Botan 向量 6 群×5 雜湊逐項一致。僅用於驗證教學，真實協議還需 M1/M2 且須走 TLS。","SRP-6a: the server stores only the verifier v=g^x — the password never travels over the network and is never stored. Outputs four lines: v/A/B/S. Default is the 1024-bit group (RFC 5054 Appendix A); for 3072 bits and above g=5. Group parameters are taken from official vectors, not transcribed by hand. Botan vectors: 6 groups × 5 hashes, all matching. For verification teaching only — a real protocol also needs M1/M2 and must run over TLS.","SRP-6a：サーバーは検証子 v=g^x のみを保存し、パスワードはネットワークにも保存にも現れません。v/A/B/S の 4 行を出力します。既定は 1024 ビット群（RFC 5054 付録 A）、3072 ビット以上では g=5、群パラメータは公式ベクトルから取得（手書きではありません）。Botan ベクトル 6 群×5 ハッシュが全項目一致。検証・教育用途のみで、実際のプロトコルには M1/M2 と TLS が必要です。","SRP-6a: 서버는 검증자 v=g^x만 저장하며 비밀번호는 네트워크로도 저장되지도 않습니다. v/A/B/S 4줄을 출력합니다. 기본값은 1024비트 군(RFC 5054 부록 A), 3072비트 이상은 g=5, 군 파라미터는 공식 벡터에서 가져왔습니다(수기 아님). Botan 벡터 6군×5해시 전 항목 일치. 검증·교육용이며 실제 프로토콜에는 M1/M2와 TLS가 필요합니다.","SRP-6a : le serveur ne stocke que le vérificateur v=g^x — le mot de passe ne transite jamais sur le réseau et n'est jamais stocké. Sortie sur quatre lignes : v/A/B/S. Groupe 1024 bits par défaut (annexe A de la RFC 5054), g=5 à partir de 3072 bits ; les paramètres de groupe proviennent de vecteurs officiels, non recopiés à la main. Vecteurs Botan : 6 groupes × 5 hachages, tous concordants. Pour l'enseignement et la vérification uniquement — un protocole réel requiert aussi M1/M2 et doit passer par TLS.","SRP-6a: der Server speichert nur den Verifikator v=g^x — das Passwort geht nie über das Netz und wird nie abgelegt. Ausgabe in vier Zeilen: v/A/B/S. Standard ist die 1024-Bit-Gruppe (RFC 5054 Anhang A), ab 3072 Bit g=5; Gruppenparameter stammen aus offiziellen Vektoren, nicht handschriftlich übertragen. Botan-Vektoren: 6 Gruppen × 5 Hashes, alle stimmen. Nur für Verifikation und Lehre — ein echtes Protokoll braucht zusätzlich M1/M2 und muss über TLS laufen.","SRP-6a: сервер хранит только верификатор v=g^x — пароль не передаётся по сети и не сохраняется. Вывод — четыре строки v/A/B/S. По умолчанию группа 1024 бита (RFC 5054, приложение A), от 3072 бит g=5; параметры групп взяты из официальных векторов, а не переписаны вручную. Векторы Botan: 6 групп × 5 хэшей, всё совпадает. Только для обучения и проверки — реальный протокол требует также M1/M2 и работы поверх TLS."],
    "nacl-box-enc": ["libsodium crypto_box：k = HSalsa20(X25519(自己的私钥, 对方公钥), 全零 16 字节)，再走 secretbox。24 字节 nonce 可随机。输出 nonce‖box。参照 PyNaCl 1.6.2。","libsodium crypto_box：k = HSalsa20(X25519(自己的私鑰, 對方公鑰), 全零 16 位元組)，再走 secretbox。24 位元組 nonce 可隨機。輸出 nonce‖box。參照 PyNaCl 1.6.2。","libsodium crypto_box: k = HSalsa20(X25519(own private key, peer public key), 16 zero bytes), then secretbox. The 24-byte nonce may be random. Output is nonce‖box. Reference: PyNaCl 1.6.2.","libsodium crypto_box：k = HSalsa20(X25519(自分の秘密鍵, 相手の公開鍵), 16 バイトのゼロ)、その後 secretbox。24 バイト nonce はランダムで構いません。出力は nonce‖box。参照：PyNaCl 1.6.2。","libsodium crypto_box: k = HSalsa20(X25519(내 개인키, 상대 공개키), 16바이트 영값) 후 secretbox. 24바이트 nonce는 무작위여도 됩니다. 출력은 nonce‖box. 참조: PyNaCl 1.6.2.","libsodium crypto_box : k = HSalsa20(X25519(clé privée propre, clé publique de l'homologue), 16 octets nuls), puis secretbox. Le nonce de 24 octets peut être aléatoire. Sortie : nonce‖box. Référence : PyNaCl 1.6.2.","libsodium crypto_box: k = HSalsa20(X25519(eigener privater Schlüssel, öffentlicher Schlüssel der Gegenseite), 16 Null-Bytes), danach secretbox. Die 24-Byte-Nonce darf zufällig sein. Ausgabe ist nonce‖box. Referenz: PyNaCl 1.6.2.","libsodium crypto_box: k = HSalsa20(X25519(свой закрытый ключ, открытый ключ другой стороны), 16 нулевых байт), затем secretbox. 24-байтовый nonce может быть случайным. Вывод: nonce‖box. Источник: PyNaCl 1.6.2."],
    "nacl-box-dec": ["输入 nonce(24)‖tag(16)‖密文，用 X25519 共享密钥解封并校验 Poly1305 tag。参照 PyNaCl 1.6.2。","輸入 nonce(24)‖tag(16)‖密文，用 X25519 共享金鑰解封並校驗 Poly1305 tag。參照 PyNaCl 1.6.2。","Input nonce(24)‖tag(16)‖ciphertext; unseal with the X25519 shared key and verify the Poly1305 tag. Reference: PyNaCl 1.6.2.","入力は nonce(24)‖tag(16)‖暗号文。X25519 共有鍵で開封し Poly1305 tag を検証します。参照：PyNaCl 1.6.2。","입력은 nonce(24)‖tag(16)‖암호문. X25519 공유키로 개봉하고 Poly1305 tag를 검증합니다. 참조: PyNaCl 1.6.2.","Entrée nonce(24)‖tag(16)‖chiffré ; ouverture avec la clé partagée X25519 et vérification du tag Poly1305. Référence : PyNaCl 1.6.2.","Eingabe nonce(24)‖tag(16)‖Chiffrat; mit dem X25519-Gemeinschaftsschlüssel öffnen und den Poly1305-Tag prüfen. Referenz: PyNaCl 1.6.2.","Вход: nonce(24)‖tag(16)‖шифротекст; распечатывание общим ключом X25519 с проверкой тега Poly1305. Источник: PyNaCl 1.6.2."],
    "nacl-sealedbox-enc": ["libsodium crypto_box_seal：生成临时 X25519 密钥对，共享密钥经 HSalsa20 派生，nonce = BLAKE2b-256(临时公钥‖接收方公钥)[0:24]。输出 = 临时公钥(32)‖box，发送方不留痕迹。默认随机生成临时密钥对（匿名）；若要可复现，在第二栏填入指定的临时私钥。参照 PyNaCl 1.6.2。","libsodium crypto_box_seal：生成臨時 X25519 金鑰對，共享金鑰經 HSalsa20 派生，nonce = BLAKE2b-256(臨時公鑰‖接收方公鑰)[0:24]。輸出 = 臨時公鑰(32)‖box，發送方不留痕跡。預設隨機生成臨時金鑰對（匿名）；若要可重現，在第二欄填入指定的臨時私鑰。參照 PyNaCl 1.6.2。","libsodium crypto_box_seal: generate an ephemeral X25519 key pair, derive the shared key via HSalsa20, nonce = BLAKE2b-256(ephemeral public key‖recipient public key)[0:24]. Output = ephemeral public key(32)‖box, leaving no trace of the sender. An ephemeral key pair is generated at random by default (anonymous); for reproducibility, put a specific ephemeral private key in the second field. Reference: PyNaCl 1.6.2.","libsodium crypto_box_seal：一時 X25519 鍵ペアを生成し、共有鍵は HSalsa20 で導出、nonce = BLAKE2b-256(一時公開鍵‖受信者公開鍵)[0:24]。出力 = 一時公開鍵(32)‖box で、送信者の痕跡は残りません。既定では一時鍵ペアをランダム生成（匿名）。再現性が必要な場合は第 2 欄に一時秘密鍵を入力。参照：PyNaCl 1.6.2。","libsodium crypto_box_seal: 임시 X25519 키 쌍을 생성하고 공유키는 HSalsa20으로 유도, nonce = BLAKE2b-256(임시 공개키‖수신자 공개키)[0:24]. 출력 = 임시 공개키(32)‖box로, 발신자 흔적이 남지 않습니다. 기본은 임시 키 쌍을 무작위 생성(익명). 재현이 필요하면 두 번째 칸에 임시 개인키를 입력. 참조: PyNaCl 1.6.2.","libsodium crypto_box_seal : génère une paire X25519 éphémère, dérive la clé partagée via HSalsa20, nonce = BLAKE2b-256(clé publique éphémère‖clé publique du destinataire)[0:24]. Sortie = clé publique éphémère(32)‖box, sans laisser de trace de l'expéditeur. Par défaut la paire éphémère est aléatoire (anonyme) ; pour reproductibilité, saisissez une clé privée éphémère précise dans le second champ. Référence : PyNaCl 1.6.2.","libsodium crypto_box_seal: erzeugt ein ephemeres X25519-Schlüsselpaar, leitet den gemeinsamen Schlüssel über HSalsa20 ab, nonce = BLAKE2b-256(ephemerer öffentlicher Schlüssel‖Empfängerschlüssel)[0:24]. Ausgabe = ephemerer öffentlicher Schlüssel(32)‖box, ohne Spur des Senders. Standardmäßig wird das Paar zufällig erzeugt (anonym); für Reproduzierbarkeit einen bestimmten ephemeren privaten Schlüssel ins zweite Feld eintragen. Referenz: PyNaCl 1.6.2.","libsodium crypto_box_seal: генерируется эфемерная пара X25519, общий ключ выводится через HSalsa20, nonce = BLAKE2b-256(эфемерный открытый ключ‖открытый ключ получателя)[0:24]. Вывод = эфемерный открытый ключ(32)‖box, отправитель не оставляет следа. По умолчанию пара создаётся случайно (анонимно); для воспроизводимости укажите конкретный эфемерный закрытый ключ во втором поле. Источник: PyNaCl 1.6.2."],
    "nacl-sealedbox-dec": ["输入 = 临时公钥(32)‖tag(16)‖密文。用接收方私钥与密文里的临时公钥重建共享密钥，nonce 同样由 BLAKE2b 派生。第二栏一般不用填；若密文不含临时公钥（已被剥离），才在此填入对方公钥。参照 PyNaCl 1.6.2。","輸入 = 臨時公鑰(32)‖tag(16)‖密文。用接收方私鑰與密文裡的臨時公鑰重建共享金鑰，nonce 同樣由 BLAKE2b 派生。第二欄一般不用填；若密文不含臨時公鑰（已被剝離），才在此填入對方公鑰。參照 PyNaCl 1.6.2。","Input = ephemeral public key(32)‖tag(16)‖ciphertext. Rebuild the shared key from the recipient private key and the ephemeral public key in the ciphertext; the nonce is likewise derived by BLAKE2b. The second field normally stays empty; only if the ciphertext does not contain the ephemeral public key (it was stripped) should you put the peer public key there. Reference: PyNaCl 1.6.2.","入力 = 一時公開鍵(32)‖tag(16)‖暗号文。受信者の秘密鍵と暗号文中の一時公開鍵から共有鍵を再構成し、nonce も同様に BLAKE2b で導出します。第 2 欄は通常は空欄で構いません。暗号文に一時公開鍵が含まれない（剥離された）場合のみ、そこに相手の公開鍵を入力します。参照：PyNaCl 1.6.2。","입력 = 임시 공개키(32)‖tag(16)‖암호문. 수신자 개인키와 암호문 속 임시 공개키로 공유키를 재구성하고 nonce도 동일하게 BLAKE2b로 유도합니다. 두 번째 칸은 보통 비워 둡니다. 암호문에 임시 공개키가 없는(제거된) 경우에만 상대 공개키를 입력합니다. 참조: PyNaCl 1.6.2.","Entrée = clé publique éphémère(32)‖tag(16)‖chiffré. Reconstruit la clé partagée à partir de la clé privée du destinataire et de la clé publique éphémère contenue dans le chiffré ; le nonce est également dérivé par BLAKE2b. Le second champ reste normalement vide ; n'y mettez la clé publique de l'homologue que si le chiffré ne contient pas la clé éphémère (elle a été retirée). Référence : PyNaCl 1.6.2.","Eingabe = ephemerer öffentlicher Schlüssel(32)‖tag(16)‖Chiffrat. Den gemeinsamen Schlüssel aus dem privaten Empfängerschlüssel und dem ephemeren öffentlichen Schlüssel im Chiffrat rekonstruieren; die Nonce wird ebenfalls per BLAKE2b abgeleitet. Das zweite Feld bleibt normalerweise leer; nur wenn das Chiffrat den ephemeren Schlüssel nicht enthält (er wurde entfernt), tragen Sie dort den öffentlichen Schlüssel der Gegenseite ein. Referenz: PyNaCl 1.6.2.","Вход = эфемерный открытый ключ(32)‖tag(16)‖шифротекст. Общий ключ восстанавливается из закрытого ключа получателя и эфемерного открытого ключа в шифротексте; nonce также выводится через BLAKE2b. Второе поле обычно оставляют пустым; указывайте открытый ключ другой стороны только если шифротекст не содержит эфемерный ключ (он был удалён). Источник: PyNaCl 1.6.2."],
    "age-enc": ["age v1 文件加密（X25519 收件人）：临时 X25519 → HKDF-SHA256 得 wrap key → ChaCha20-Poly1305 封装 16 字节 file key → header MAC=HMAC-SHA256(头+\"---\") → 载荷=16 字节 nonce‖STREAM(64KiB 分块)。参照 age v1.2.1 官方 testdata。","age v1 檔案加密（X25519 收件人）：臨時 X25519 → HKDF-SHA256 得 wrap key → ChaCha20-Poly1305 封裝 16 位元組 file key → header MAC=HMAC-SHA256(頭+\"---\") → 載荷=16 位元組 nonce‖STREAM(64KiB 分塊)。參照 age v1.2.1 官方 testdata。","age v1 file encryption (X25519 recipient): ephemeral X25519 → HKDF-SHA256 for the wrap key → ChaCha20-Poly1305 wraps the 16-byte file key → header MAC=HMAC-SHA256(header+\"---\") → payload = 16-byte nonce‖STREAM(64KiB chunks). Reference: official age v1.2.1 testdata.","age v1 ファイル暗号化（X25519 受信者）：一時 X25519 → HKDF-SHA256 で wrap key → ChaCha20-Poly1305 で 16 バイトの file key をラップ → header MAC=HMAC-SHA256(ヘッダー+\"---\") → ペイロード = 16 バイト nonce‖STREAM(64KiB チャンク)。参照：age v1.2.1 公式 testdata。","age v1 파일 암호화(X25519 수신자): 임시 X25519 → HKDF-SHA256로 wrap key → ChaCha20-Poly1305로 16바이트 file key 래핑 → header MAC=HMAC-SHA256(헤더+\"---\") → 페이로드 = 16바이트 nonce‖STREAM(64KiB 청크). 참조: age v1.2.1 공식 testdata.","Chiffrement de fichier age v1 (destinataire X25519) : X25519 éphémère → HKDF-SHA256 pour la clé d'enveloppement → ChaCha20-Poly1305 enveloppe la clé de fichier de 16 octets → MAC d'en-tête = HMAC-SHA256(en-tête+\"---\") → charge utile = nonce 16 octets‖STREAM(blocs de 64 Kio). Référence : testdata officiel age v1.2.1.","age-v1-Dateiverschlüsselung (X25519-Empfänger): ephemeres X25519 → HKDF-SHA256 für den Wrap-Key → ChaCha20-Poly1305 verpackt den 16-Byte-Dateischlüssel → Header-MAC = HMAC-SHA256(Header+\"---\") → Nutzlast = 16-Byte-Nonce‖STREAM(64-KiB-Blöcke). Referenz: offizielle age-v1.2.1-Testdaten.","Шифрование файлов age v1 (получатель X25519): эфемерный X25519 → HKDF-SHA256 для ключа обёртки → ChaCha20-Poly1305 оборачивает 16-байтовый файловый ключ → MAC заголовка = HMAC-SHA256(заголовок+\"---\") → полезная нагрузка = 16-байтовый nonce‖STREAM(блоки по 64 КиБ). Источник: официальные testdata age v1.2.1."],
    "age-dec": ["age v1 文件解密。先校验 header MAC（不匹配直接报错，不会返回错误明文），再按 64KiB 分块解 STREAM。输入框填 .age 文件内容：可以是原始文本、base64，或 -----BEGIN AGE ENCRYPTED FILE----- 装甲文本。参照 FiloSottile/age v1.2.1。","age v1 檔案解密。先校驗 header MAC（不匹配直接報錯，不會返回錯誤明文），再按 64KiB 分塊解 STREAM。輸入框填 .age 檔案內容：可以是原始文本、base64，或 -----BEGIN AGE ENCRYPTED FILE----- 裝甲文本。參照 FiloSottile/age v1.2.1。","age v1 file decryption. The header MAC is verified first (a mismatch raises an error immediately and never returns wrong plaintext), then STREAM is decrypted in 64KiB chunks. Paste the .age file contents into the input box: raw text, base64, or -----BEGIN AGE ENCRYPTED FILE----- armored text. Reference: FiloSottile/age v1.2.1.","age v1 ファイル復号。まず header MAC を検証し（不一致なら即エラー、誤った平文は返しません）、その後 STREAM を 64KiB チャンクで復号します。入力欄に .age ファイルの内容を貼り付けます。生テキスト、base64、または -----BEGIN AGE ENCRYPTED FILE----- の装甲テキストが使えます。参照：FiloSottile/age v1.2.1。","age v1 파일 복호화. 먼저 header MAC을 검증하고(불일치 시 즉시 오류, 잘못된 평문을 반환하지 않음) 그다음 STREAM을 64KiB 청크로 복호화합니다. 입력 칸에 .age 파일 내용을 붙여넣습니다. 원본 텍스트, base64, 또는 -----BEGIN AGE ENCRYPTED FILE----- 아머 텍스트가 가능합니다. 참조: FiloSottile/age v1.2.1.","Déchiffrement de fichier age v1. Le MAC d'en-tête est vérifié d'abord (toute discordance déclenche une erreur immédiate, jamais un clair erroné), puis STREAM est déchiffré par blocs de 64 Kio. Collez le contenu du fichier .age dans la zone de saisie : texte brut, base64 ou texte blindé -----BEGIN AGE ENCRYPTED FILE-----. Référence : FiloSottile/age v1.2.1.","age-v1-Dateientschlüsselung. Zuerst wird der Header-MAC geprüft (bei Abweichung sofort ein Fehler, niemals falscher Klartext), dann STREAM in 64-KiB-Blöcken entschlüsselt. In das Eingabefeld den Inhalt der .age-Datei einfügen: Rohdaten, base64 oder gepanzerter Text -----BEGIN AGE ENCRYPTED FILE-----. Referenz: FiloSottile/age v1.2.1.","Расшифрование файлов age v1. Сначала проверяется MAC заголовка (при несовпадении сразу ошибка, никогда не возвращается неверный открытый текст), затем STREAM расшифровывается блоками по 64 КиБ. В поле ввода вставьте содержимое файла .age: обычный текст, base64 или бронированный текст -----BEGIN AGE ENCRYPTED FILE-----. Источник: FiloSottile/age v1.2.1."]
  };

  var I18N = window.I18N || (window.I18N = {});
  var TABLES = I18N.__ALGO_TABLES || (I18N.__ALGO_TABLES = []);
  TABLES.push(INFO);
  I18N.__ALGO_INFO_ASYM = INFO;
})();
